package com.smartbi.query;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.net.*;import java.util.*;import java.util.stream.Collectors;
@Component public class JdbcUrlPolicy{
 private final Set<String> allowedHosts;private final Set<Integer> allowedPorts;
 public JdbcUrlPolicy(@Value("${smartbi.network.allowed-hosts:}")String hosts,@Value("${smartbi.network.allowed-ports:5432}")String ports){allowedHosts=Arrays.stream(hosts.split(",")).map(String::trim).filter(s->!s.isEmpty()).map(JdbcUrlPolicy::canonicalHost).collect(Collectors.toUnmodifiableSet());try{allowedPorts=Arrays.stream(ports.split(",")).map(String::trim).filter(s->!s.isEmpty()).map(Integer::valueOf).filter(p->p>0&&p<=65535).collect(Collectors.toUnmodifiableSet());}catch(RuntimeException e){throw new IllegalArgumentException("Invalid smartbi.network.allowed-ports",e);}}
 public void validatePostgreSql(String jdbcUrl){Endpoint endpoint=parse(jdbcUrl);if(!allowedHosts.contains(endpoint.host())||!allowedPorts.contains(endpoint.port()))throw new QueryException("DATASOURCE_URL_FORBIDDEN","Data source host or port is not allow-listed");}
 /** Re-resolve immediately before pool creation/use. Network egress policy remains the rebinding backstop. */
 public void validateResolvedTarget(String jdbcUrl){Endpoint endpoint=parse(jdbcUrl);validatePostgreSql(jdbcUrl);try{InetAddress[] addresses=InetAddress.getAllByName(endpoint.host());if(addresses.length==0)forbidden();for(InetAddress address:addresses)if(address.isAnyLocalAddress()||address.isLoopbackAddress()||address.isLinkLocalAddress()||address.isMulticastAddress())forbidden();}catch(UnknownHostException e){throw new QueryException("DATASOURCE_HOST_UNRESOLVED","Data source host could not be resolved");}}
 private static Endpoint parse(String jdbcUrl){if(jdbcUrl==null||!jdbcUrl.startsWith("jdbc:postgresql://"))return invalid();try{String raw=jdbcUrl.substring(5);URI uri=URI.create(raw);String authority=uri.getRawAuthority(),host=uri.getHost();int port=uri.getPort()<0?5432:uri.getPort();if(!"postgresql".equals(uri.getScheme())||authority==null||host==null||uri.getRawUserInfo()!=null||uri.getRawQuery()!=null||uri.getRawFragment()!=null||uri.getPath()==null||!uri.getPath().matches("/[A-Za-z0-9_.-]+")||authority.indexOf(',')>=0||authority.indexOf('@')>=0||port<1||port>65535)return invalid();return new Endpoint(canonicalHost(host),port);}catch(QueryException e){throw e;}catch(RuntimeException e){return invalid();}}
 private static String canonicalHost(String host){String value=host.trim();if(value.startsWith("[")&&value.endsWith("]"))value=value.substring(1,value.length()-1);return value.indexOf(':')>=0?value.toLowerCase(Locale.ROOT):IDN.toASCII(value,IDN.USE_STD3_ASCII_RULES).toLowerCase(Locale.ROOT);}
 private static <T>T invalid(){throw new QueryException("DATASOURCE_URL_INVALID","A canonical single-host PostgreSQL JDBC URL without user-info, fragments, or connection parameters is required");}
 private static void forbidden(){throw new QueryException("DATASOURCE_URL_FORBIDDEN","Resolved data source target is not permitted");}
 private record Endpoint(String host,int port){}
}
